<?php require '../includes/auth.php';require_role('admin');$pdo=db();$queries=['Buyers'=>"SELECT COUNT(*) FROM users WHERE role='buyer'",'Approved sellers'=>"SELECT COUNT(*) FROM seller_profiles WHERE approval_status='approved'",'Pending approvals'=>"SELECT COUNT(*) FROM seller_profiles WHERE approval_status='pending'",'Products'=>'SELECT COUNT(*) FROM products','Orders'=>'SELECT COUNT(*) FROM orders','Revenue'=>"SELECT COALESCE(SUM(total),0) FROM orders WHERE status='Delivered'"];$stats=[];foreach($queries as $k=>$q)$stats[$k]=$pdo->query($q)->fetchColumn();$pageTitle='Admin dashboard';require '../includes/header.php';?><div class="dashboard-hero"><p class="eyebrow">MARKETPLACE CONTROL</p><h1>FreshCatch admin</h1><p>Monitor sellers, listings, orders, and marketplace health.</p></div><section class="stats admin-stats"><?php foreach($stats as $label=>$v):?><div><small><?=e($label)?></small><strong><?=$label==='Revenue'?'₹'.number_format($v,0):$v?></strong></div><?php endforeach;?></section><section class="quick-links"><a href="<?=url('admin/sellers.php')?>">✓<b>Seller approvals</b><span>Review pending shops</span></a><a href="<?=url('admin/categories.php')?>">◉<b>Categories</b><span>Manage marketplace taxonomy</span></a><a href="<?=url('admin/orders.php')?>">📦<b>All orders</b><span>View marketplace fulfillment</span></a><a href="<?=url('admin/users.php')?>">☺<b>Users</b><span>Manage access and status</span></a></section><?php require '../includes/footer.php'; ?>
